class Person:
    def __init__(self, name):
        self.name = name

    def greet(self):
        print(f"Hello, my name is {self.name}.")


# Define the Student class inheriting from Person
class Student(Person):
    def study(self):
        print(f"{self.name} is studying hard.")


# Create student1
student1 = Student('Alex')

# Call inherited and unique methods
student1.greet()
student1.study()
